exec((__import__('pathlib').Path(__file__).parent/'gaosi_a.py').read_text(encoding='utf-8').split("B('01出术'")[0])
B('05风向',[
C('han_zhen','韩珍','韩珍外表是能以逼真表情讲述故事的妙龄女子，实际却负责监视一名携带毒品运输信息的联络人。她事先等在荒屋内，另有两个同伙在外接应，准备在信息交付后将送信人灭口。计划因她过早露出杀意而发生变故，联络人惊叫逃出，附近的俞诚闻声来到；韩珍临时伏地装死，把刀夹在腋下，使慌乱的俞诚碰到刀柄，留下可以嫁祸的指纹。同伙抓回真正目标后再用这柄刀杀人，风向和听声位置又制造了证词上的表面矛盾。事后她主动接近调查，编出唇膏里藏着天价秘密的说法，表情一度使高斯相信，李玉芳却抓住对方不该随便泄露这样信息的逻辑破绽。俞诚获释后，韩珍又带人去住处劫持，暴露了自己对失物的追索。警方出现时她退回屋内，想沿水管逃走，最终无路可逃。终局的她是被识破的毒品犯罪参与者，长于表演与临机嫁祸，却并不精于每一层逻辑；不能把演技写成催眠，也不能把一次成功装尸体写成假死神通。','劫持俞诚时暴露，试沿水管逃离失败，被捕。','妙龄女子，能控制表情讲得逼真；不添加特定服饰。','完成组织的灭口与信息回收，避免自己暴露。','现场受扰便改用伪装，追索失物时又冒险亲自出面。','装死、编造证词、同伙协作与攀水管；普通人的犯罪手段。',[(1108,1138,'李玉芳识别她的说辞问题'),(1149,1172,'绑架与逃亡失败'),(1193,1211,'灭口、装死与嫁祸全貌')],[('预定行动被陌生人打断','对方尚不知她身份','迅速扮成无害者或受害者。'),('关键物品失踪','怀疑知情者带走','用伪造故事探问，再升级接近。'),('警方突然出现','尚有建筑物可利用','寻找旁路逃脱，不原地背诵计划。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':1,'sustain':2,'range':1,'combat':2},tier='并'),
C('yu_cheng','俞诚','俞诚是被荒屋杀人案卷进来的普通中年人。他听见女子惊叫，走近查看，以为发现尸体，慌乱中碰了刀柄，后来短暂离开又回到屋内，看到的情况却发生变化。由于自己的经历听来过于离奇，他先用另一个版本对付警方，反而使时间、地点和行为都显得可疑。高斯追问之后，他终于重新说出自己所见，包括前后出现的不同女子以及中间那几分钟空白；即使如此，他仍觉得没有人会信。李玉芳却以证词内部没有不能解释的矛盾为由争取释放他，并暗中跟随保护，俞诚对此毫不知情，回家仍神思恍惚。真正的犯罪者随即出现，把他拗手架出房门，企图逼出失踪唇膏的下落；李玉芳现身开枪，才救下他并完成抓捕。终局的俞诚不是凭直觉破解案子的侦探，而是一个因怕真话不可信而把处境弄坏、最终靠准确叙述和他人核验脱险的证人。他对不同视角、听觉与记忆的限制有了惨痛认识，跨世界可以提供有缺口的见闻，不能替自己补齐从未看见的幕后行动。','获释后险被韩珍等绑架，获李玉芳保护，嫌疑得以澄清。','普通中年男子，受讯时嗫嚅，获释后神思恍惚。','洗脱未犯的谋杀嫌疑，恢复普通生活。','担心没人相信时会隐瞒或改口，被耐心追问才讲真经过。','亲历记忆和证言；没有专业侦查与战斗能力。',[(908,1054,'更正证词及碰刀经过'),(1091,1105,'获释与茫然'),(1149,1172,'被绑架和救援')],[('所见违背常识','害怕说出反被怀疑','可能先犹豫，应逐项还原实际见闻。'),('被人追问自己没有的东西','对方明显威胁','求助和强调不知道，不虚构线索。'),('调查者愿核验细节','可以承认先前隐瞒','纠正错误，接受记忆仍有空白。')]),
C('han_henchmen','韩珍的两名同伙','两名男子在韩珍的计划中承担屋外接应和直接控制目标的工作。他们没有独立姓名，也没有可区分的长期背景，因此以共同行动条目记录。携信息的女子发现灭口企图后逃出，是他们把她重新捉回荒屋，随后让真正的杀人发生在已沾有俞诚指纹的刀下。这个配合使韩珍的临时装死不只是独立骗局，而成为可以把路过者推入嫌疑的完整犯罪链。关键唇膏下落不明以后，他们又跟随韩珍潜入俞诚住所，一个拗住他的手，另一个凶狠地推押，准备把他带走。面对李玉芳突然出现，两人共同把人质向前一推，分头向楼下逃；李玉芳开枪击中后，他们仍跑出一段，最终一人不支倒地，另一人被巡警截住。终局二人已落网，不能默认仍有组织可支援。他们的体力、围堵和人质手段都是普通肉身层面的协作；中弹后还能短暂奔跑不等于防弹，人数优势也不等于能自动压倒任何角色。没有证据证明他们知道运输网络全貌，口供和选择应受各自所知范围限制。','绑架时被李玉芳射伤后逃跑失败，均被捕。','两名成年男子，外貌未细写，动作凶狠。','为韩珍的灭口与追索行动提供强制控制。','遭伏击就推开人质抢路逃跑。','合力抓捕、拗手押送和利用人质阻滞追击。',[(1155,1172,'押人、推人质与被捕'),(1199,1211,'追回联络人并配合杀害')],[('目标试图逃离','同伙已布置外部拦截','合力围堵而非单人逞强。'),('需要带走知情者','认为现场无人保护','控制手臂与移动方向。'),('武装力量突然介入','原先优势丧失','丢开人质抢出口，仍会受伤落网。')],roles=['反派'],scores={'physical':2,'energy':0,'scope':1,'sustain':2,'range':1,'combat':2},tier='并')],excluded=[{'name':'唇膏联络人','reason':'犯罪信息携带者与被害人，但受骗且无独立对抗行动，未作为主角展开。'}])
B('06古墨',[
C('shang_daqing','商大庆','商大庆是继承深厚家产的富豪，住宅古老而宏大，珍藏包括一批旧墨。他并不靠温和的待客方式展示地位，面对来替古物摄影的高斯，冷淡与傲慢始终让对方感到难堪，仆人也仿效这种态度。高斯后来从一锭旧墨中得到红宝石，以为所有同类墨都藏有财富，带着十万英镑来买他的三十六锭，商大庆并不急着谈，先让客人等自己听报告、喝汤，足足耗去许久，连坐下的位置也不准备。对方提出买卖，他把简单句子拆开嘲笑，不相信这个摄影师真能拿出足够钱；最后随口说只要箱里全是钱，不论多少就出售。高斯当面倒出钞票，以他的商业名声迫使兑现，他便命人交货，没有在钱到手后毁约。故事未证明商大庆知道墨中藏宝，更没证明他参与骗局，因此终局只把他视作阶层与商业交涉上的阶段性对立者。他会以等待、轻蔑和场面安排压低别人，遇到自己公开承诺也仍有名誉约束；财富带来的议价权必须依附真实财产，不能算作身体强度或让每个对手服从的能力。','履行承诺，以一箱现钞出售三十六锭古墨，未被揭出犯罪。','富豪，惯于大模大样坐着、玩烟斗；具体年龄衣着未固定。','维持自己居高临下的地位和交易主导。','用拖延和嘲笑试探对方底气，公开承诺后仍兑现。','财富、收藏和商业场面控制；无超常技能。',[(3,11,'家世与宅院'),(529,638,'等待、羞辱、赌式开价及交货')],[('求见者地位不如自己','认为对方有求于他','拉长等待，先展示谁掌控节奏。'),('对方提出出乎意料的交易','尚不相信其实力','以轻蔑和夸张条件回应。'),('自己在众人前给出承诺','对方满足了原话条件','顾及名声履约，不任意改口。')],roles=['阶段性对立者'],uncertainties=['不能把傲慢等同参与诈骗，原文无此证据。']),
C('ink_bar_woman','古墨案中的酒吧女郎','她在一条通宵营业的酒吧街工作，以甜美笑容和水灵眼睛吸引已急于打发时间的高斯。高斯刚得横财，又因更大的财富想象焦躁等待天亮，饮酒以后她一直伴在身边，听见他烦恼时间过得太慢，便顺势拿出小盒里的药丸，声称能让他忘掉烦恼，并提醒价格和避开警察。她把危险物包装成贴心的解决办法，利用的并不是神奇魅惑，而是对方已经形成的醉意和愿望。高斯明知是何物仍服下，在药效和酒精混合下陷入幻觉；与此同时，她拿走他的钱包，直接抽取里面的钞票。高斯试图阻止，却很快以为自己会飞，失去正常判断，后来因醉酒闹事等原因出现在拘留所。叙事没有交代她是否被抓，也没有给姓名或其他犯罪史。终局的她是一次明确利用脆弱状态偷窃的加害者，能力只到主动贴近、推销药物和顺手取财；未说明的药物配方、精确作用时间与让任何人服从的效果都不能补造。面对清醒拒绝或第三者介入，她的控制条件会显著减少。','取得高斯钱包中现金，随后去向及是否受查未写。','年轻美丽，眼睛水灵，衣着用于招揽客人；不额外细化。','借酒客的欲望与失防取得金钱。','顺着对方烦恼提供诱惑，等待注意力涣散再下手。','近身社交、提供致幻药物与扒取钱包；依赖受害者服用和醉态。',[(380,418,'接近、提供药丸和抽钱'),(421,454,'高斯失控与后果')],[('客人急于逃避烦恼','已有酒意和消费欲','把付费诱惑说成即时解脱。'),('对方注意力散乱','财物在可接近处','转移话题同时取财。'),('被清醒地拒绝','无法靠贴近降低戒心','不具强制催眠能力，只能另寻机会。')],roles=['反派'])],li=False,excluded=[{'name':'小吴','reason':'单书助手和保释协助者，未发现第二部实际登场。'},{'name':'李玉芳','reason':'此篇部分出现为高斯药物幻觉，不能用来证明实际参与。'}])
B('07怪房子',[
C('peng_shiyuan','彭士元','彭士元是怪屋所属家族的后人，也是真正尝试理解屋中声响的人。他不轻易接受鬼魂解释，已把不同声音记录整理，发现会周而复始出现，曾考虑机械可能，却被两个问题困住：房子建成时没有现代录音装置，藏在墙中的机械又如何持续得到动力。与高斯共同听见杖声、喘息和呻吟时，他愿把记录拿出来对照，并指出高斯最初解释仍有缺口，不因对方兴奋就随声附和。真正使他难下决定的不是单纯害怕鬼，而是祖先留下不得损坏房屋的禁令；家族把这条遗言看作不能触犯的规范，拆墙既可能揭谜，也可能使他背上不孝之名。最终在高斯鼓励下，他郑重选择一起用工具凿开墙，看到齿轮和机械摩擦发声，又发现建屋先祖原来就在等待后人有勇气不迷信鬼，也不盲守遗言。终局的彭士元保留谨慎求证、重视推理完整性和承认传统压力的特点。他没有因此掌握百年前所有机械设计，只是完成一次重要的核验；新的情境中会先理解规则为何存在，再决定是否越过，而不应被改成凡遇传统必反对的口号人物。','与高斯破墙发现机械与祖先留言，打破禁令后得到事实解释。','外貌未详；思考凝重，讨论时会侧头回忆记录。','弄清祖屋怪声，同时处理事实与祖训之间的冲突。','坚持指出解释漏洞，最终为求证承担传统压力。','现象记录、比较与合力检验；未显示超常或万能工程能力。',[(523,601,'记录、机械假说与动力疑问'),(603,645,'决定破墙、发现装置和先祖本意')],[('解释听来合理','仍有关键资源条件没交代','提出漏洞，要求把机制讲完整。'),('核验触犯继承的规则','禁止缘由已不清楚','权衡责任后作具体决定。'),('真相推翻长久恐惧','证据可展示给他人','把装置和记录说明白，不再渲染神秘。')])],li=False,excluded=[{'name':'罗夫、王余、杨坚及聚会主人','reason':'本书一次性朋友，推动赌赛与讨论，未找到跨书实际登场。'},{'name':'彭家建屋先祖','reason':'仅经遗留机关和留言出现的历史人物；设计求知测试，不确定属于反派。'}])
B('08怪人奇骗',[
C('zhang_bing','张炳','张炳是才出狱又行骗的老手，曾冒充印度土王或阿拉伯酋长，这次把自己包装成赫布王子，先以怪异外貌和长久站望引起高斯注意。他利用几十年前的悬案和藏宝地图制造真实背景，又故意弄错一个字、找错地方，使高斯以为是自己凭聪明发现了关键，主动投入计划。所谓王子并不急于直接向他索钱，反而在同伙的石屋前表示价钱过高、自己付不起，让高斯愿意先垫全部房款；随后又以宝藏分成和未来皇宫贵宾的幻想加强关系。两人饮酒研究地图，张炳不断描绘小岛风光，借共同期待压过产权、宝物和身份的查证。交易完成后，他准备以买工具为由离开，却遇见跟踪同伙而来的警察；警察直接叫出本名，戳破外号，他试跳窗也被抓住。终局的张炳失去伪造身份，未证明有任何寻宝天赋。他擅长让受害者自以为掌握主动，诈骗的强点是叙事、诱导和伙伴分工，弱点则是经不起独立身份核查；历史悬案是真的，也不能让其补出的解释自动变真。','骗局收款时被警方识破本名，跳窗未成，被捕。','刻意塑成怪人、异国王子形象；真实外貌不详。','以假藏宝机会骗走高斯积蓄。','装作不愿占便宜，遇熟识警察立即想逃。','身份扮演、历史故事拼接与让目标自发现的诱导。',[(549,588,'装缺钱、分成许诺与幻想'),(618,641,'本名曝光及骗局解释')],[('目标以聪明自负','喜欢发现别人没发现的秘密','留下可被他主动纠正的小错。'),('必须让目标付钱','直接索求会引起戒心','表现为自己钱不够，让对方主动垫付。'),('出现熟悉旧案的人','假身份可能马上崩溃','优先逃离，无法靠话术抹掉档案。')],roles=['反派'],aliases=['赫布王子']),
C('wang_amao','王阿毛（怪人奇骗）','王阿毛是张炳藏宝骗局中的搭档，扮演被目标认定压着宝藏的石屋主人。骗局让高斯以为必须买下石屋才能挖出翡翠，因此他无需夸赞房子或主动推销，只说自己喜欢清静、不想出让，默默等对方不断加价。面对一万元、一万五、两万直到两万二的报价，他掌握着表面出售权的优势；直到认为钱够了才答应，又要求看到现钞。高斯次日取出几乎全部存款来交易，王阿毛原想不办手续，后来应对方要求签了简单字据，数钱便离开，把继续演戏的任务留给张炳。这一分工把无价值石屋包装成获得巨额财富的唯一通道。他没有预料到，自己另涉窃案，警方早已跟踪数日，交易刚完成就被押回屋，顺势暴露了整个骗局。终局的他是被捕的协同诈骗者，不能因为表现得像当地业主就拥有所有地产或真实藏宝权。他的手法是装不情愿、借目标的沉没投入抬价，遇到能核查产权、身份和同伙关系的对象便会失去优势；没有证据表明他本人也会张炳全部冒充技巧。','因被警方跟踪，在交易后被抓并带回石屋，骗局败露。','壮汉，扮成简陋石屋主人。','以普通石屋的虚构藏宝价值取得高额房款。','沉默拖价，钱到手就离开。','配合骗局的议价与表演；另涉窃案但具体技法不明。',[(549,577,'不愿出售姿态与抬价'),(599,641,'交易、被捕与真实搭档关系')],[('买家已经相信隐藏价值','自己掌握入口','不急报价，让对方主动抬价。'),('付款人要求手续','简单凭证足以令其安心','提供最低限度配合以完成收款。'),('身份被独立调查触及','假故事无法继续保护','会挣扎或失措，不具逃脱保证。')],roles=['反派'])])
B('09鬼照片',[
C('wang_quan','汪权','汪权与诸新荣合作经营贩毒组织多年，原有案底使他的活动受警方注意，组织内一度由没有相同负担的搭档占上风。他没有真的退场，而是用钱收买档案环节，把另一个死者的指纹记录换成自己的，让警方相信自己跳楼自杀，从此以死人的名义继续活动。注意力解除后，他的势力增长，诸新荣感到被排挤，暗拍他仍活着的照片，想借摄影家发表鬼照片引警方重查。汪权从告密者得知计划，枪杀旧搭档，再劫住已拿到照片的高斯，要求取回底片并准备灭口。他喜欢在枪口优势下揭露部分真相，却仍不肯让受害者了解全部业务；对方可能已向警方提及照片时，他的得意立即转为紧张。高斯借受命打电话通知办公室的机会暗中联络李玉芳，警方找到来取照片的手下并让其合作，突入现场。汪权拒绝放枪，开火伤警，退至窗口后坠楼死亡。这次死亡真实结束了他的伪装。终局卡保留腐败关系、持枪和组织权力的条件性能力，所谓死后活动全是档案欺诈，不具灵体、不死或更换他人真实指纹的超能力。','拒捕枪战中从十四楼坠下死亡，假死身份彻底曝光。','成年犯罪头目，具体衣饰未详；常以阴笑和枪口控制谈话。','摆脱警方注意，独占组织优势并灭除知情者。','被问到警方是否知情时紧张，受围堵仍开枪拒捕。','贿赂与档案调包、组织威慑、手枪；依赖内应和具体记录系统。',[(466,536,'合伙、杀人及假死方法'),(538,604,'拒捕死亡与警方查明')],[('旧身份阻碍活动','有可收买的系统环节','尝试改变记录而非真的改变身体。'),('同伴威胁主导权','其掌握可暴露证据','抢先灭口并追回资料。'),('警方已打破密室优势','仍有枪械与出口','可能拼命抵抗，承担真实伤亡风险。')],roles=['反派'],revive=True,scores=GUN,tier='并',ooc=['不得把伪造死亡记录演成真复活或亡灵能力。']),
C('zhu_xinrong','诸新荣','诸新荣与汪权合伙十多年，双方的犯罪关系并不是他向高斯讲述的房东与房客。汪权有旧案底时，他在组织内占优势；搭档用假死摆脱警方注意以后，他反被挤到次要位置，遂想到把对方重新推回调查视线。他用远摄镜头拍到明明已被记录死亡的汪权，带着这些看似奇异的照片去找高斯，装作无意拍到死去房客的老实人，希望借摄影家的好奇和公开发表扩大影响。计划的精巧处是让警方自然怀疑，而不必自己站出来告发共同罪行；它的致命弱点则是内部关系并不牢固，一个手下向汪权告密，使他在照片已经交出后被旧搭档枪杀。后来李玉芳才把鬼照片还原为争权的犯罪链条。终局的诸新荣是已死的组织合伙人，行为目的在夺回地位，不能因把证据交给摄影家便改写成无私举报者。他确有观察、摄录和扮演无辜者的手段，却不擅长控制所有内应，拍到死者影像也完全来自汪权仍活着的事实，不是通灵摄影。','因策划曝光汪权遭告密，被汪权枪杀。','表演无害讲述者，稳定外貌未给；摄影器材属具体行动工具。','借警方重新约束搭档，夺回自己在贩毒组织的位置。','不直接出面指控，改用可传播的奇异证据诱导第三者。','远摄取证、伪装关系与借好奇者传播；没有鬼影能力。',[(466,483,'假房东说法与合伙杀人事实'),(570,581,'争权目的、远摄照片与告密后果')],[('搭档绕过原有制衡','自己利益遭排挤','寻找能借外力重新限制对方的证据。'),('直接告发会牵连自身','第三者又有发布能力','包装成无辜发现，请其代为传播。'),('内部信任不稳','计划需经手下执行','存在被泄密风险，不能自动掌控全团伙。')],roles=['反派'],revive=True)])
